// Wraps the worker generated by OpenNext so we can add a Cron Trigger handler.
// Build first with `opennextjs-cloudflare build`; that creates .open-next/worker.js.
// @ts-expect-error: generated at build time
import { default as handler } from "./.open-next/worker.js";

type Env = { APP_URL: string; CRON_SECRET: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };

export default {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    // Run the daily job through the normal app route so it shares all app code.
    const req = new Request(new URL("/api/cron/daily", env.APP_URL), {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

// @ts-expect-error: generated at build time
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
